CREATE TABLE ${primehrSchema}.ld_evaluation_task (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,completion_case_id VARCHAR(36) NOT NULL,offering_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,framework_fingerprint VARCHAR(64) NOT NULL,level_type VARCHAR(30) NOT NULL,required BIT NOT NULL,score_method VARCHAR(20) NOT NULL,passing_score DECIMAL(19,6),evidence_requirements VARCHAR(3000) NOT NULL,instrument_guidance VARCHAR(3000) NOT NULL,evaluator_role VARCHAR(20) NOT NULL,assigned_evaluator_no VARCHAR(100) NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,current_result_id VARCHAR(36),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_eval_task_completion FOREIGN KEY(completion_case_id) REFERENCES ${primehrSchema}.ld_completion_case(id),CONSTRAINT fk_ld_eval_task_offering FOREIGN KEY(offering_id) REFERENCES ${primehrSchema}.ld_offering(id),CONSTRAINT fk_ld_eval_task_framework FOREIGN KEY(framework_version_id) REFERENCES ${primehrSchema}.ld_evaluation_framework_version(id),CONSTRAINT uk_ld_evaluation_task_level UNIQUE(agency_id,completion_case_id,level_type),CONSTRAINT ck_ld_eval_task_level CHECK(level_type IN ('REACTION','LEARNING','BEHAVIOR_APPLICATION','RESULTS','RETURN_OF_EXPECTATION')),CONSTRAINT ck_ld_eval_task_score CHECK(score_method IN ('QUALITATIVE','PERCENTAGE','POINTS','PASS_FAIL')),CONSTRAINT ck_ld_eval_task_role CHECK(evaluator_role IN ('PARTICIPANT','SUPERVISOR','LD_STAFF')),CONSTRAINT ck_ld_eval_task_status CHECK(status IN ('OPEN','SATISFIED')));
CREATE INDEX ix_ld_eval_task_assigned ON ${primehrSchema}.ld_evaluation_task(agency_id,assigned_evaluator_no,status,due_date);CREATE INDEX ix_ld_eval_task_employee ON ${primehrSchema}.ld_evaluation_task(agency_id,employee_no,due_date);
CREATE TABLE ${primehrSchema}.ld_evaluation_result (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,task_id VARCHAR(36) NOT NULL,result_revision INT NOT NULL,supersedes_result_id VARCHAR(36),score DECIMAL(19,6),passed BIT,narrative VARCHAR(4000) NOT NULL,evidence_reference VARCHAR(500),status VARCHAR(20) NOT NULL,submitted_by VARCHAR(100) NOT NULL,submitted_at DATETIMEOFFSET NOT NULL,decided_by VARCHAR(100),decided_at DATETIMEOFFSET,decision_reason VARCHAR(2000),result_fingerprint VARCHAR(64) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_eval_result_task FOREIGN KEY(task_id) REFERENCES ${primehrSchema}.ld_evaluation_task(id),CONSTRAINT fk_ld_eval_result_prior FOREIGN KEY(supersedes_result_id) REFERENCES ${primehrSchema}.ld_evaluation_result(id),CONSTRAINT uk_ld_evaluation_result_revision UNIQUE(agency_id,task_id,result_revision),CONSTRAINT ck_ld_eval_result_revision CHECK(result_revision>=1),CONSTRAINT ck_ld_eval_result_status CHECK(status IN ('SUBMITTED','VERIFIED','RETURNED')));
ALTER TABLE ${primehrSchema}.ld_evaluation_task ADD CONSTRAINT fk_ld_eval_task_current_result FOREIGN KEY(current_result_id) REFERENCES ${primehrSchema}.ld_evaluation_result(id);
CREATE INDEX ix_ld_eval_result_task ON ${primehrSchema}.ld_evaluation_result(agency_id,task_id,result_revision);
CREATE TABLE ${primehrSchema}.ld_learning_action_plan (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,completion_case_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,supervisor_employee_no VARCHAR(100) NOT NULL,application_objective VARCHAR(3000) NOT NULL,success_measure VARCHAR(3000) NOT NULL,target_date DATE NOT NULL,status VARCHAR(20) NOT NULL,content_revision INT NOT NULL,submitted_by VARCHAR(100),submitted_at DATETIMEOFFSET,follow_up_outcome VARCHAR(4000),evidence_reference VARCHAR(500),decided_by VARCHAR(100),decided_at DATETIMEOFFSET,decision_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_lap_completion FOREIGN KEY(completion_case_id) REFERENCES ${primehrSchema}.ld_completion_case(id),CONSTRAINT uk_ld_lap_completion UNIQUE(agency_id,completion_case_id),CONSTRAINT ck_ld_lap_status CHECK(status IN ('DRAFT','SUBMITTED','VERIFIED','RETURNED')),CONSTRAINT ck_ld_lap_revision CHECK(content_revision>=1));
CREATE INDEX ix_ld_lap_employee ON ${primehrSchema}.ld_learning_action_plan(agency_id,employee_no,status,target_date);CREATE INDEX ix_ld_lap_supervisor ON ${primehrSchema}.ld_learning_action_plan(agency_id,supervisor_employee_no,status,target_date);
